.hero {
  background: linear-gradient(160deg, #0a0a1a 0%, #1a1a3e 100%);
  padding: 120px 24px 100px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle at 30% 50%, rgba(99, 102, 241, 0.08) 0%, transparent 50%);
  pointer-events: none;
}

.hero__container {
  max-width: 800px;
  margin: 0 auto;
  position: relative;
  z-index: 1;
}

.hero__date {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-accent, #6366f1);
  text-transform: uppercase;
  letter-spacing: 0.15em;
  margin-bottom: 16px;
}

.hero__title {
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 800;
  color: var(--color-text, #f8fafc);
  line-height: 1.1;
  margin: 0 0 16px;
}

.hero__location {
  font-size: 1.25rem;
  color: var(--color-text-muted, #94a3b8);
  margin-bottom: 8px;
}

.hero__tagline {
  font-size: 1.25rem;
  color: var(--color-text-muted, #94a3b8);
  margin-bottom: 40px;
}

.hero__cta {
  display: inline-block;
  padding: 16px 48px;
  background: var(--color-accent, #6366f1);
  color: #fff;
  font-size: 1.125rem;
  font-weight: 700;
  border-radius: 8px;
  text-decoration: none;
  transition: transform 0.2s, box-shadow 0.2s;
}

.hero__cta:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(99, 102, 241, 0.35);
}

@media (max-width: 768px) {
  .hero {
    padding: 80px 20px 64px;
  }
}

.speakers {
  background: var(--color-bg, #0a0a1a);
  padding: 96px 24px;
}

.speakers__container {
  max-width: 1100px;
  margin: 0 auto;
}

.speakers__heading {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--color-text, #f8fafc);
  text-align: center;
  margin: 0 0 64px;
}

.speakers__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 40px;
}

.speakers__card {
  text-align: center;
  padding: 32px 16px;
  border-radius: 12px;
  background: var(--color-surface, #12122a);
  transition: transform 0.2s;
}

.speakers__card:hover {
  transform: translateY(-4px);
}

.speakers__avatar {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  margin: 0 auto 24px;
  background: linear-gradient(135deg, var(--color-accent, #6366f1), #818cf8);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.speakers__avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.speakers__initials {
  font-size: 2.5rem;
  font-weight: 700;
  color: #fff;
  text-transform: uppercase;
}

.speakers__name {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-text, #f8fafc);
  margin: 0 0 4px;
}

.speakers__role {
  font-size: 0.95rem;
  color: var(--color-text-muted, #94a3b8);
  margin: 0;
}

@media (max-width: 900px) {
  .speakers__grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .speakers__grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }

  .speakers {
    padding: 64px 20px;
  }
}

.schedule {
  background: var(--color-surface, #12122a);
  padding: 96px 24px;
}

.schedule__container {
  max-width: 900px;
  margin: 0 auto;
}

.schedule__heading {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--color-text, #f8fafc);
  text-align: center;
  margin: 0 0 64px;
}

.schedule__day {
  margin-bottom: 48px;
}

.schedule__day:last-child {
  margin-bottom: 0;
}

.schedule__day-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-accent, #6366f1);
  margin: 0 0 24px;
  padding-bottom: 12px;
  border-bottom: 2px solid rgba(99, 102, 241, 0.2);
}

.schedule__timeline {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.schedule__event {
  display: flex;
  align-items: flex-start;
  gap: 24px;
  padding: 20px 0;
  border-bottom: 1px solid rgba(148, 163, 184, 0.1);
}

.schedule__event:last-child {
  border-bottom: none;
}

.schedule__time {
  flex-shrink: 0;
  width: 100px;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--color-accent, #6366f1);
  padding-top: 2px;
}

.schedule__details {
  flex: 1;
}

.schedule__event-title {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--color-text, #f8fafc);
  margin: 0 0 4px;
}

.schedule__speaker {
  font-size: 0.9rem;
  color: var(--color-text-muted, #94a3b8);
  margin: 0;
}

@media (max-width: 600px) {
  .schedule {
    padding: 64px 20px;
  }

  .schedule__event {
    flex-direction: column;
    gap: 4px;
  }

  .schedule__time {
    width: auto;
  }
}

.register {
  background: linear-gradient(160deg, var(--color-accent, #6366f1), #4f46e5);
  padding: 96px 24px;
  text-align: center;
}

.register__container {
  max-width: 700px;
  margin: 0 auto;
}

.register__heading {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: #fff;
  margin: 0 0 16px;
}

.register__description {
  font-size: 1.15rem;
  color: rgba(255, 255, 255, 0.85);
  line-height: 1.7;
  margin: 0 0 24px;
}

.register__price {
  font-size: 1.5rem;
  font-weight: 700;
  color: #fff;
  margin: 0 0 32px;
}

.register__cta {
  display: inline-block;
  padding: 16px 56px;
  background: #fff;
  color: var(--color-accent, #6366f1);
  font-size: 1.125rem;
  font-weight: 700;
  border-radius: 8px;
  text-decoration: none;
  transition: transform 0.2s, box-shadow 0.2s;
}

.register__cta:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.2);
}

@media (max-width: 600px) {
  .register {
    padding: 64px 20px;
  }
}

sharedCss:
:root {
  --color-bg: #0a0a1a;
  --color-surface: #12122a;
  --color-accent: #6366f1;
  --color-text: #f8fafc;
  --color-text-muted: #94a3b8;
  --font-heading: system-ui, -apple-system, sans-serif;
  --font-body: system-ui, -apple-system, sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  font-family: var(--font-body);
  background: var(--color-bg);
  color: var(--color-text);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
}

img {
  max-width: 100%;
  height: auto;
}

a {
  color: inherit;
  text-decoration: none;
}
